import org.apache.commons.lang.text.ExtendedMessageFormat;
import org.apache.commons.lang.text.FormatFactory;
import java.text.Format;
import java.text.SimpleDateFormat;
import java.util.*;

public class Explore {
    static class LowerFormatFactory implements FormatFactory {
        public Format getFormat(String name, String arguments, Locale locale) {
            return new UpperLowerFormat(false);
        }
    }
    static class UpperLowerFormat extends Format {
        boolean upper;
        UpperLowerFormat(boolean upper) { this.upper = upper; }
        public StringBuffer format(Object obj, StringBuffer toAppendTo, java.text.FieldPosition pos) {
            String s = obj.toString();
            return toAppendTo.append(upper ? s.toUpperCase() : s.toLowerCase());
        }
        public Object parseObject(String source, java.text.ParsePosition pos) { return source; }
    }

    public static void main(String[] args) throws Exception {
        Map registry = new HashMap();
        registry.put("lower", new LowerFormatFactory());

        // Basic custom format test
        ExtendedMessageFormat emf = new ExtendedMessageFormat("{0,lower}", registry);
        System.out.println("format: [" + emf.format(new Object[]{"ABC"}) + "]");
        System.out.println("toPattern: [" + emf.toPattern() + "]");

        // Mixed custom + standard
        ExtendedMessageFormat emf2 = new ExtendedMessageFormat("{0,lower} and {1,number}", registry);
        System.out.println("format2: [" + emf2.format(new Object[]{"ABC", 42}) + "]");
        System.out.println("toPattern2: [" + emf2.toPattern() + "]");

        // No registry at all -> standard behavior
        ExtendedMessageFormat emf3 = new ExtendedMessageFormat("{0} and {1,number}");
        System.out.println("format3: [" + emf3.format(new Object[]{"x", 7}) + "]");
        System.out.println("toPattern3: [" + emf3.toPattern() + "]");

        // registry present but format name unknown -> fallback to std MessageFormat handling
        ExtendedMessageFormat emf4 = new ExtendedMessageFormat("{0,number}", registry);
        System.out.println("format4: [" + emf4.format(new Object[]{42}) + "]");
        System.out.println("toPattern4: [" + emf4.toPattern() + "]");

        // whitespace around index e.g {0 , lower}
        try {
            ExtendedMessageFormat emf5 = new ExtendedMessageFormat("{0 ,lower}", registry);
            System.out.println("format5: [" + emf5.format(new Object[]{"ABC"}) + "]");
            System.out.println("toPattern5: [" + emf5.toPattern() + "]");
        } catch (Exception e) {
            System.out.println("emf5 exception: " + e);
        }

        // quote handling - literal braces
        ExtendedMessageFormat emf6 = new ExtendedMessageFormat("'{'0'}'", registry);
        System.out.println("format6: [" + emf6.format(new Object[]{"ABC"}) + "]");

        // setFormat should throw
        try {
            emf.setFormat(0, null);
            System.out.println("setFormat did NOT throw");
        } catch (UnsupportedOperationException e) {
            System.out.println("setFormat threw UOE as expected");
        }

        // unterminated quote
        try {
            new ExtendedMessageFormat("'unterminated", registry);
            System.out.println("no exception for unterminated quote");
        } catch (IllegalArgumentException e) {
            System.out.println("unterminated quote threw IAE: " + e.getMessage());
        }

        // unterminated format element
        try {
            new ExtendedMessageFormat("{0,lower", registry);
            System.out.println("no exception for unterminated format element");
        } catch (IllegalArgumentException e) {
            System.out.println("unterminated format element threw IAE: " + e.getMessage());
        }

        // invalid argument index (non-digit)
        try {
            new ExtendedMessageFormat("{abc,lower}", registry);
            System.out.println("no exception for invalid arg index");
        } catch (IllegalArgumentException e) {
            System.out.println("invalid arg index threw IAE: " + e.getMessage());
        }

        // missing arg index entirely: {}
        try {
            ExtendedMessageFormat bad = new ExtendedMessageFormat("{}", registry);
            System.out.println("no exception for empty braces, toPattern=" + bad.toPattern());
        } catch (Exception e) {
            System.out.println("empty braces exception: " + e);
        }

        // equals/hashCode
        ExtendedMessageFormat a1 = new ExtendedMessageFormat("{0}", Locale.US);
        ExtendedMessageFormat a2 = new ExtendedMessageFormat("{0}", Locale.US);
        System.out.println("equals: " + a1.equals(a2));

        // getLocale
        System.out.println("locale: " + a1.getLocale());

        // applyPattern re-apply with registry null constructor but then no registry effect
        ExtendedMessageFormat noReg = new ExtendedMessageFormat("{0,lower}");
        System.out.println("noReg format (should treat lower as unknown std format?) : ");
        try {
            System.out.println("[" + noReg.format(new Object[]{"ABC"}) + "]");
        } catch (Exception e) {
            System.out.println("noReg exception: " + e);
        }
    }
}
